scwin.fn_SetComboCode = function() {
    cmb_SME_YN.CBData = scwin.strCbd_SME_YN;
    cmb_HDCOM_YN.CBData = scwin.strCbd_HDCOM_YN;
    cmb_NPARVALSTK_YN.CBData = scwin.strCbd_NPARVALSTK_YN;
    cmb_SME_YN.setSelectedIndex(0);
    cmb_HDCOM_YN.setSelectedIndex(0);
    cmb_NPARVALSTK_YN.setSelectedIndex(0);

    //주거래은행
    dts_MaintrBkCd.DataID = "/CodeAction.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listInstCd&For=";
    dts_MaintrBkCd.Reset();
    scwin.fn_searchCode();
};
scwin.fn_searchCode = function() {
    /*
    00443-통화ISO코드-일반사항-CURR_ISO_CD-cmb_CurrIsoCd
    00443-액면가통화ISO코드-일반사항-PARVAL_CURR_ISO_CD-cmb_ParvalCurrIsoCd
    00443-재무통화ISO코드-일반사항-FNC_CURR_ISO_CD-cmb_CapCurrIsoCd
    00443-공모가통화ISO코드-일반사항-PUBPRC_CURR_ISO_CD-cmb_PubprcCurrIsoCd
    00443-공모가예정통화ISO코드-일반사항-PUBPRC_SCHDL_CURR_ISO_CD-cmb_PubprcSchdlCurrIsoCd
    00685-명의개서대행기관-일반사항-TRANSSTK_AGNT_CD-cmb_TransstkAgntCd
    00755 - 외부감사인코드
    */
    var arrCid = [{
        cid: "CURR_ISO_CD",
        cnm: "cmb_CURR_ISO_CD"
    }, {
        cid: "CURR_ISO_CD",
        cnm: "cmb_PARVAL_CURR_ISO_CD"
    }, {
        cid: "CURR_ISO_CD",
        cnm: "cmb_FNC_CURR_ISO_CD"
    }, {
        cid: "CURR_ISO_CD",
        cnm: "cmb_PUBPRC_CURR_ISO_CD"
    }, {
        cid: "CURR_ISO_CD",
        cnm: "cmb_PUBPRC_SCHDL_CURR_ISO_CD"
    }, {
        cid: "CURR_ISO_CD",
        cnm: "cmb_NETINCM_CURR_ISO_CD"
    }, {
        cid: "TRANSSTK_AGNT_CD",
        cnm: "cmb_TRANSSTK_AGNT_CD"
    }, {
        cid: "EXT_AUDTR_CD",
        cnm: "cmb_EXT_AUDTR_CD"
    }];
    var objCod;
    var url = "/CodeAction.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='CURR_ISO_CD','TRANSSTK_AGNT_CD','EXT_AUDTR_CD'";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    var strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        if (objCod == null) {
            $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "";
        for (j = 1; j <= dts_Cod.getTotalRow(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") == arrCid[i].cid) {
                strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
};
scwin.fn_initForm = function(initTyp) {
    if (initTyp == "C") {
        img_COM_NM.src = "../img/btn_search.gif";
        img_COM_NM.setDisabled(false);
    } else if (initTyp == "X") {
        img_COM_NM.src = "../img/btn_search_d.gif";
        img_COM_NM.setDisabled(true);
    }
};
scwin.fn_initLabel = function(secugrpId) {
    //alert("secugrpId:"+secugrpId);
    lb_LIST_SHRS.setValue("*상장(예정)주식수");
    lb_PARVAL.setValue("액면가/1주당자본금");
    lb_PUBOFR_SHRS.setValue("공모주식수");
    $c.stf.showObj(label_59, false);
    $c.stf.showObj(label_78, false);
    $c.stf.showObj(label_79, false);
    $c.stf.showObj(label_81, false);
    $c.stf.showObj(edt_NETINCM_AMT1, false);
    $c.stf.showObj(cmb_NETINCM_CURR_ISO_CD, false);
    if (secugrpId == "FS") {
        $c.cm.PanelToGroupBox(panel_Forn_Item);
        $c.stf.showObj(label_47, false);
        $c.stf.showObj(label_80, false);
        $c.stf.showObj(label_78, true);
        $c.stf.showObj(label_79, true);
        $c.stf.showObj(label_81, true);
        $c.stf.showObj(label_dr, true);
        $c.stf.showObj(edt_NETINCM_AMT1, true);
        $c.stf.showObj(cmb_NETINCM_CURR_ISO_CD, true);
        $c.stf.showObj(panel_Forn_Item, true);
        $c.stf.showObj(cmb_CURR_ISO_CD, false);
        edt_PER1DR_FORNSTK_RTO.setDisabled(true);
        if ($c.stf.getObjectValue(cmb_PUBPRC_CURR_ISO_CD) == "") {
            $c.stf.setObjectValue(cmb_PUBPRC_CURR_ISO_CD, "KRW");
        }
        if ($c.stf.getObjectValue(cmb_PUBPRC_SCHDL_CURR_ISO_CD) == "") {
            $c.stf.setObjectValue(cmb_PUBPRC_SCHDL_CURR_ISO_CD, "KRW");
        }
    } else if (secugrpId == "DR") {
        $c.cm.PanelToGroupBox(panel_Forn_Item);
        $c.stf.showObj(label_74, false);
        $c.stf.showObj(label_75, false);
        $c.stf.showObj(label_76, false);
        $c.stf.showObj(label_77, false);
        $c.stf.showObj(label_59, true);
        $c.stf.showObj(label_dr, true);
        $c.stf.showObj(cmb_PARVAL_CURR_ISO_CD, false);
        $c.stf.showObj(cmb_FNC_CURR_ISO_CD, false);
        $c.stf.showObj(cmb_PUBPRC_CURR_ISO_CD, false);
        $c.stf.showObj(cmb_PUBPRC_SCHDL_CURR_ISO_CD, false);
        $c.stf.showObj(cmb_NETINCM_CURR_ISO_CD, false);
        $c.stf.showObj(panel_Forn_Item, true);
        edt_PER1DR_FORNSTK_RTO.setDisabled(false);
        lb_LIST_SHRS.setValue("*상장DR수");
        lb_PARVAL.setValue("액면가(원주기준)/1주당자본금");
        lb_PUBOFR_SHRS.setValue("공모DR수");
    } else {
        $c.stf.showObj(label_dr, false);
        $c.stf.showObj(panel_Forn_Item, false);
    }
    edt_LISTDD_CLSPRC.setValue("0");
    edt_FST_BAS_PRC.setValue("0");
};
scwin.fn_GetParStdInd = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = $c.stf.getObjectValue(txb_STD_IND_CD); // 코드값을 포함할 컨트롤
    arrPar[1] = $c.stf.getObjectValue(txb_STD_IND_NM); // 명칭값을 포함할 컨트롤

    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetParStdInd = function(arrPar) {
    /*
    gAfStdIndCd = arrPar[0].STD_IND_CD;
    if (js_market == '1') {
    } else if (js_market == '2') {
    	txb_STD_IND_CD.value = arrPar[0].KOSDAQ_STD_IND_CD;
    }
    */
    txb_STD_IND_CD.setValue(arrPar[0].STD_IND_CD);
    txb_STD_IND_NM.setValue(arrPar[0].IND_NM);
};
scwin.fn_GetParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = $c.stf.getObjectValue(txb_ISUR_CD); // 코드값을 포함할 컨트롤
    arrPar[1] = $c.stf.getObjectValue(txb_COM_NM); // 명칭값을 포함할 컨트롤
    arrPar[2] = $c.stf.getObjectValue(cmb_SECUGRP_ID);
    arrPar[3] = scwin.mktTpCd;
    arrPar[4] = SEARCH_TYP_SEC; //신규등록시
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetParIsur = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        /*if(arrPar[0].LIST_DD == ""){
            alert('보통주 등록이 선행되어야 합니다');
        	return;
        }*/

        txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
        txb_COM_NM.setValue(arrPar[0].COM_NM);
        txb_COM_ENG_NM.setValue(arrPar[0].COM_ENG_NM);
        txb_CMSTK_LIST_DD.setValue(arrPar[0].LIST_DD);
        scwin.vListBzSeq = arrPar[0].LIST_BZ_SEQ;
        if ($c.stf.getObjectValue(txb_ISUR_CD) != "") {
            var url = "/KindStk.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=readNewRegPreList&inputMessageId=KIND_STK_PREEXAM_INOUT";
            url += "&ISUR_CD=" + txb_ISUR_CD.getValue();
            url += "&LIST_DD=" + txb_CMSTK_LIST_DD.getValue();
            url += "&LIST_BZ_SEQ=" + scwin.vListBzSeq;
            dts_Item.DataID = encodeURI(url);
            dts_Item.Reset();
            if (dts_Item.getCellData(1, "SECUGRP_ID") == "") {
                var parentWin = $c.frame.path("../");
                dts_Item.setCellData(1, "SECUGRP_ID", $c.stf.getObjectValue(parentWin.cmb_NEW_SECUGRP_ID));
            }
        }
    }
};
scwin.fn_GetParIsuCd = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = $c.stf.getObjectValue(txb_ISUR_CD); // 코드값을 포함할 컨트롤
    arrPar[1] = scwin.mktTpCd;
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetParIsuCd = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        txb_ISU_CD.setValue(arrPar[0].ISU_CD);
        txb_ISU_NM.setValue(arrPar[0].ISU_NM);
    }
};
scwin.fn_SetParForIsuCd = function(arrPar) {
    txb_ISU_CD.setValue(arrPar[0].ISU_CD);
    txb_ISU_NM.setValue(arrPar[0].ISU_NM);
};
scwin.fn_read_sync = function() {
    //alert("LIST_BZ_SEQ :"+vListBzSeq);
    dts_Item.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
    dts_Item.setCellData(1, "LIST_BZ_SEQ", scwin.vListBzSeq);
    var url = "/KindStk.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=readKindStkPreList&inputMessageId=KIND_STK_PREEXAM_SEARCH_OUT";
    url += "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    url += "&LIST_BZ_SEQ=" + scwin.vListBzSeq;
    url += "&SPOT_ISU_TRD_MKT_TP_CD=" + scwin.mktTpCd;
    dts_Item.DataID = encodeURI(url);
    dts_Item.Reset();
    scwin.fn_changeForm(dts_Item.getCellData(1, "INVSTG_PROG_STAT_CD"));
};
scwin.strCbd_INVSTG_PROG_STAT_CD_1 = "01^심사진행,02^심사완료,03^심사완료(6개월경과등),04^심사연기,05^심사철회,06^심사기각";
scwin.strCbd_INVSTG_PROG_STAT_CD_2 = "10^신규상장 - 비상장,11^신규상장 - 코스닥법인,21^재상장 - 인적분할,22^재상장 - 폐지,23^재상장 - 합병,24^재상장 - 물적분할";
scwin.fn_changeForm = function(gStatCd) {
    //alert("[gStatCd]:"+gStatCd);
    //alert("[gStatCd.charAt(0) ]:"+gStatCd.charAt(0) );
    if (gStatCd != "" && gStatCd.charAt(0) != '0') {
        cmb_INVSTG_PROG_STAT_CD.setDisabled(false);
        cmb_INVSTG_PROG_STAT_CD.CBData = scwin.strCbd_INVSTG_PROG_STAT_CD_2;
    } else {
        cmb_INVSTG_PROG_STAT_CD.setDisabled(false);
        cmb_INVSTG_PROG_STAT_CD.CBData = scwin.strCbd_INVSTG_PROG_STAT_CD_1;
    }
    cmb_INVSTG_PROG_STAT_CD.BindColVal = gStatCd;
};
scwin.fn_getLeadComNoStr = function() {
    return dts_Item.getCellData(1, "LEADCOM_MBR_NM_STR");
};
scwin.fn_setLeadComNMStr = function(str_no, str_nm) {
    dts_Item.setCellData(1, "LEADCOM_MBR_NO_STR", str_no);
    dts_Item.setCellData(1, "LEADCOM_MBR_NM_STR", str_nm);
    txb_LEADCOM_MBR_NM_STR.setValue(str_nm);
    //alert("[str_no] :"+str_no);

};
scwin.fn_CheckForm = function() {
    if ($c.stf.getObjectValue(txb_ISUR_CD) == "") {
        $c.win.alert("[법인]을 선택하세요.");
        img_COM_NM.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_COM_NM) == "") {
        $c.win.alert("[한글법인명]을 입력하세요..");
        txb_COM_NM.focus();
        return false;
    }

    //2009.05.12 법인명의 '주식회사' 를 '(주)'로 변경, '(주)'가 없는 법인인 경우 입력하도록..(국내법인인 경우만)
    if (dts_Item.getCellData(1, "SECUGRP_ID") == "ST") {
        //alert("[SECUGRP_ID] :"+dts_Item.NameValue(1,"SECUGRP_ID"));
        var tmpComNm_pre = $c.stf.getObjectValue(txb_COM_NM);
        var tmpComNm_next = tmpComNm_pre.replace('주식회사', '');
        if (tmpComNm_pre != tmpComNm_next) {
            $c.win.alert("한글회사명에 '주식회사'는 '(주)'로 입력, 영문회사명에 'CO.,LTD' 를 입력하세요");
            txb_COM_NM.focus();
            return false;
        }
        tmpComNm_pre = $c.stf.getObjectValue(txb_COM_NM);
        tmpComNm_next = tmpComNm_pre.replace('(주)', '');
        if (tmpComNm_pre == tmpComNm_next) {
            $c.win.alert("한글회사명에 '(주)' 를 입력하세요");
            txb_COM_NM.focus();
            return false;
        }
    }
    if ($c.stf.getObjectValue(txb_COM_ENG_NM) == "") {
        $c.win.alert("[영문법인명]을 입력하세요..");
        txb_COM_ENG_NM.focus();
        return false;
    }
    if (chk_WEB_DP_YN.checked && chk_WEB_NOPN_YN.checked) {
        $c.win.alert("[비공개 심사시 선택] 와 [비공개(인적분할 재상시)]를 중복으로 선택하실수 없습니다.");
        chk_WEB_DP_YN.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_INVSTG_BILL_ACPT_DD) == "") {
        //alert("[청구서접수일]를 입력하세요.");edt_INVSTG_BILL_ACPT_DD.focus();return false;

    }
    if ($c.stf.getObjectValue(txb_APPL_COM_CHRG_NM) == '') {
        $c.win.alert('신청회사 담당자명을 입력하십시오');
        txb_APPL_COM_CHRG_NM.focus();
        return;
    }
    if ($c.stf.getObjectValue(txb_APPL_COM_CHRG_TEL_NO) == "") {
        $c.win.alert('담당자 연락처를 입력하십시오');
        txb_APPL_COM_CHRG_TEL_NO.focus();
        return;
    }
    if ($c.stf.getObjectValue(cmb_INVSTG_PROG_STAT_CD) == "02" && $c.stf.getObjectValue(edt_INVSTG_COMPLT_DD) == "") {
        //alert("[심사결과확정일]을 선택하십시오. \n상장구분이 심사완료인 경우 등록필수항목입니다.");edt_INVSTG_COMPLT_DD.focus();return false;

    }
    if ($c.stf.getObjectValue(cmb_INVSTG_PROG_STAT_CD) == "") {
        $c.win.alert("[심사상태]을 선택하세요.");
        cmb_INVSTG_PROG_STAT_CD.focus();
        return false;
    }

    //alert("[parseInt(txb_LIST_SHRS.value,10)."+parseInt(txb_LIST_SHRS.value,10));
    if (parseInt($c.stf.getObjectValue(edt_LIST_SHRS), 10) <= 0 || $c.stf.getObjectValue(edt_LIST_SHRS).length == 0) {
        //alert("[상장(예정)주식수]를 입력하세요.");edt_LIST_SHRS.focus(); return false;

    }
    if (dts_Item.getCellData(1, "SECUGRP_ID") == "FS") {
        if ($c.stf.getObjectValue(edt_NETINCM_AMT).length == 0) {
            $c.win.alert("[당기순이익(원화)]를 입력하세요.");
            edt_NETINCM_AMT.focus();
            return false;
        }
        if ($c.stf.getObjectValue(edt_NETINCM_AMT1).length == 0) {
            $c.win.alert("[당기순이익(외화)]를 입력하세요.");
            edt_NETINCM_AMT1.focus();
            return false;
        }
        // 통화 필수체크
        if ($c.stf.getObjectValue(cmb_PARVAL_CURR_ISO_CD) == "") {
            //alert("[액면가 통화표시]를 입력하세요.");cmb_PARVAL_CURR_ISO_CD.focus();return false;

        }
        if ($c.stf.getObjectValue(cmb_NETINCM_CURR_ISO_CD) == "") {
            $c.win.alert("[당기순이익(외화) 통화표시]를 입력하세요.");
            cmb_NETINCM_CURR_ISO_CD.focus();
            return false;
        }
    } else {
        if ($c.stf.getObjectValue(edt_NETINCM_AMT).length == 0) {
            $c.win.alert("[당기순이익]을 입력하세요.");
            edt_NETINCM_AMT.focus();
            return false;
        }
    }
    if ($c.stf.getObjectValue(txb_CNTR_ISO_NM) == "410") {
        if (parseInt($c.stf.getObjectValue(edt_PARVAL), 18) <= 0 || $c.stf.getObjectValue(edt_PARVAL).length == 0) {
            $c.win.alert("[액면가]를 입력하세요.");
            edt_PARVAL.focus();
            return false;
        }
    }

    /*if (getObjectValue(edt_LIST_DD).length  == 0 ) {
    		alert("[상장예정일]을 입력하세요.");btn_LIST_DD.focus();return false;
    }*/

    return true;
};
scwin.fn_save = function() {
    scwin.TR_JOB = 'I';
    if (scwin.fn_CheckForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        scwin.vBzProcsNo = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo);
        if (scwin.vBzProcsNo.length != 14) {
            $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            // 
            // ********************************************************************

            dts_Item.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo); /*ORG SRC: dts_Item.UserStatus(1) = TB_JOB_INSERT;*/ X = TB_JOB_INSERT;
            scwin.fn_trs();
        }
    }
};
scwin.fn_update = function() {
    scwin.TR_JOB = 'U';
    if (scwin.fn_CheckForm()) {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return; /*ORG SRC: dts_Item.UserStatus(1) = TB_JOB_UPDATE;*/ X = TB_JOB_UPDATE;
        scwin.fn_trs();
    }
};
scwin.fn_trs = function() {
    var vScrenProcTpCd;
    if (scwin.TR_JOB == "I") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_02;
    } else if (scwin.TR_JOB == "U") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_03;
    }
    dts_Item.setCellData(1, "EXAMPRN_EMP_NO", js_emp_no);
    dts_Item.setCellData(1, "FST_EXAMPRN_EMP_NO", js_emp_no);
    dts_Item.setCellData(1, "WEB_DP_YN", (chk_WEB_DP_YN.checked ? "N" : "Y")); //반대로 체크한다..
    dts_Item.setCellData(1, "WEB_NOPN_YN", (chk_WEB_NOPN_YN.checked ? "Y" : "N"));
    dts_Item.setCellData(1, "SPOT_ISU_TRD_MKT_TP_CD", scwin.mktTpCd);
    trs_Save.Action = "/KindStk.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenProcTpCd + "&method=savePreList";
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Item)";
    trs_Save.Post();
};
scwin.fn_parentRefresh = function() {
    var fr_fn_list_sync = $c.frame.path("../").fn_list_sync;
    fr_fn_list_sync();
};



