scwin.dts_Item_OnLoadCompleted = function(rowcount) {
    chk_WEB_DP_YN.setValue((dts_Item.getCellData(1, "WEB_DP_YN") == "N"));
    chk_WEB_NOPN_YN.setValue((dts_Item.getCellData(1, "WEB_NOPN_YN") == "Y"));
    if ($c.stf.getObjectValue(cmb_NPARVALSTK_YN) == "Y") {
        $c.stf.showObj(edt_PARVAL, false);
        $c.stf.showObj(edt_PER1STK_CAP, true);
    } else {
        $c.stf.showObj(edt_PARVAL, true);
        $c.stf.showObj(edt_PER1STK_CAP, false);
    }
    if (scwin.vBzProcsNo == "") {
        buttonSet.setInsertStatus();
        scwin.fn_initForm('C');
    } else {
        scwin.fn_initForm('X');
        buttonSet.setUpdateStatus();
    }
    if (js_dep_cd != '2500' && js_dep_cd != '2520' && js_dep_cd != '2540' &&
        js_dep_cd != '3300' && js_dep_cd != '3320' && js_dep_cd != '3330' &&
        js_dep_cd != '3E00' && js_dep_cd != '3E10' && js_dep_cd != '3E20' && js_dep_cd != '3E30' && js_dep_cd != '3E40' &&
        js_dep_cd != '2615' && js_dep_cd != '3G20') {
        //심사1팀,심사2팀
        buttonSet.setErrorStatus(); //disable 시킨다.

    }
};
scwin.trs_Save_OnSuccess = function() {
    $c.lc.fn_alertMsg('S');
    scwin.fn_read_sync();
    scwin.fn_parentRefresh();
    if (buttonSet.status == "U") {
        var parentWin = $c.frame.path("../");
        parentWin.dts_List.setFocusedCell(scwin.rowPos, 0);
    }
};
scwin.trs_Save_OnFail = function() {
